static_assert(offsetof(uniserve_unpermute_call, scales) == 24, "the operator crate's layout of uniserve_unpermute_call");
static_assert(offsetof(uniserve_unpermute_call, tokens) == 32, "the operator crate's layout of uniserve_unpermute_call");
static_assert(offsetof(uniserve_unpermute_call, top) == 40, "the operator crate's layout of uniserve_unpermute_call");
